callout.js:
// callout: a "Hide"/"Show" button for the text. The loader calls the block's init once per
// <div data-component="callout">; defineBlock('callout', …) makes it from the setup below, safe to
// call twice and disposed with the page. block-kit (the module `foliwake`, served by the engine
// and added to every code release): `fields` are the block's fields by name, ctx.state re-renders
// the view when it changes, ctx.t reads the labels of callout.json `ui`, ctx.emit sends a bubbling
// "block:<type>" event with the block's name and key.
import { defineBlock, html } from 'foliwake';

export default defineBlock('callout', ({ title = '' }, ctx) => {
  const hidden = ctx.state(false);
  ctx.effect(() => ctx.attrs(ctx.root, { 'data-collapsed': hidden.value }));
  ctx.render(() => html`<button type="button" aria-expanded=${!hidden.value} @click=${() => {
    hidden.value = !hidden.value;
    ctx.emit('toggle', { hidden: hidden.value, title });
  }}>${ctx.t(hidden.value ? 'show' : 'hide')}</button>`);
});

callout.css:
/* callout: Callout. Fields: callout.json; examples: callout.example.md.
   HTML: <div data-component="callout" class="callout">[<h3 data-field="title">]<div data-field="text"><p>…</p></div></div>
   Every rule is in @layer blocks and under [data-component="callout"], so it styles only this
   block; colours and spacing come from the site's variables (styles/styles.css), with fallbacks. */

@layer blocks {
  [data-component="callout"] {
    margin-block: var(--space, 1rem);
    padding: var(--space, 1rem);
    border: 1px solid var(--color-border, #d4d4d8);
    border-radius: var(--radius, 0.75rem);
    background: var(--color-surface, transparent);

    & [data-field="title"] {
      margin: 0 0 0.5rem;
      font-size: 1.05rem;
    }

    & [data-field="text"] > p:last-child { margin-bottom: 0; }

    &[data-collapsed] > [data-field="text"] { display: none; }
  }
}

